import{_ as h,C as t,o as b,c as v,a3 as s,E as r,j as a,a as n}from"./chunks/framework.1Rq3Io9y.js";const y=JSON.parse('{"title":"Séance 8 — Estimer le temps et monter le devis","description":"","frontmatter":{"title":"Séance 8 — Estimer le temps et monter le devis","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/08-estimer-et-chiffrer.md","filePath":"modules/01-faisabilite/08-estimer-et-chiffrer.md"}'),f={name:"modules/01-faisabilite/08-estimer-et-chiffrer.md"};function q(_,e,x,T,L,P){const i=t("FilDeLaSeance"),o=t("FigurePoids"),l=t("FigureOublis"),u=t("FigureTroisChiffres"),d=t("EstimationTroisChiffres"),c=t("FigureEcheancier"),p=t("FigureDevis"),g=t("FigureTroisFacons"),m=t("EntrerDansLeBudget");return b(),v("div",null,[e[0]||(e[0]=s('<h1 id="seance-8-—-estimer-le-temps-et-monter-le-devis" tabindex="-1">Séance 8 — Estimer le temps et monter le devis <a class="header-anchor" href="#seance-8-—-estimer-le-temps-et-monter-le-devis" aria-label="Permalink to &quot;Séance 8 — Estimer le temps et monter le devis&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li><strong>Choisir</strong> un outil avec des critères pondérés.</li><li><strong>Estimer</strong> le travail en trois chiffres et le placer dans un <strong>échéancier</strong> avec un coussin.</li><li>Monter un <strong>devis</strong> sur trois ans et proposer <strong>trois façons d&#39;entrer dans le budget</strong>.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La matière d&#39;abord, en grand groupe, puis le <strong>Lab 08</strong> en équipe jusqu&#39;à la fin de la soirée.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour sur le Lab 07</td></tr><tr><td style="text-align:left;">18 h 45</td><td style="text-align:left;">Vos questions sur l&#39;évaluation 2</td></tr><tr><td style="text-align:left;">18 h 55</td><td style="text-align:left;">La mise en situation et le plan de la soirée</td></tr><tr><td style="text-align:left;">19 h 00</td><td style="text-align:left;">Étape 1 — Choisir avec des critères</td></tr><tr><td style="text-align:left;">19 h 05</td><td style="text-align:left;">Étape 2 — Estimer le travail</td></tr><tr><td style="text-align:left;">19 h 15</td><td style="text-align:left;">Activité 1 — L&#39;estimation de la boulangerie</td></tr><tr><td style="text-align:left;">19 h 35</td><td style="text-align:left;">Étape 3 — Placer le travail dans le temps</td></tr><tr><td style="text-align:left;">19 h 45</td><td style="text-align:left;">Étape 4 — Chiffrer et entrer dans le budget</td></tr><tr><td style="text-align:left;">19 h 55</td><td style="text-align:left;">Activité 2 — Faire entrer la boulangerie dans le budget</td></tr><tr><td style="text-align:left;">20 h 15</td><td style="text-align:left;">La suite du cours · consignes du Lab 08 et à faire à la maison</td></tr><tr><td style="text-align:left;">20 h 25</td><td style="text-align:left;">Marge pour les questions</td></tr><tr><td style="text-align:left;">20 h 35</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 50</td><td style="text-align:left;"><a href="./../../labs/lab08-estimer-et-chiffrer">Lab 08 — Estimer et chiffrer la proposition</a>, jusqu&#39;à la fin de la soirée</td></tr></tbody></table><p>Le <strong>retour sur le Lab 08</strong> aura lieu au début de la séance 9.</p><hr><h2 id="retour-lab-07" tabindex="-1">Retour sur le Lab 07 <a class="header-anchor" href="#retour-lab-07" aria-label="Permalink to &quot;Retour sur le Lab 07 {#retour-lab-07}&quot;">​</a></h2><p>Dans le chat : <strong>le fichier qui vous a donné le plus de mal</strong>, et ce que vous avez fait.</p><h2 id="vos-questions-sur-l-evaluation-2" tabindex="-1">Vos questions sur l&#39;évaluation 2 <a class="header-anchor" href="#vos-questions-sur-l-evaluation-2" aria-label="Permalink to &quot;Vos questions sur l&#39;évaluation 2&quot;">​</a></h2><p>Dans le chat, maintenant, pour tout le groupe.</p><hr><h2 id="mise-en-situation" tabindex="-1">La mise en situation et le plan de la soirée <a class="header-anchor" href="#mise-en-situation" aria-label="Permalink to &quot;La mise en situation et le plan de la soirée {#mise-en-situation}&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Mise en situation, inventée pour le cours : la boulangerie</strong><br> Ce soir, on ne travaille pas sur Aventure Saint-Maurice. On s&#39;exerce sur un <strong>petit projet inventé</strong>, plus simple, pour voir chaque méthode une fois au complet. Les outils de la boulangerie sont inventés aussi. <ul class="list-disc pl-5"><li>Une boulangerie de quartier veut que ses clients <strong>commandent en ligne pour le samedi</strong>.</li><li>Le menu <strong>change chaque semaine</strong> et la propriétaire veut le changer seule.</li><li>Elle garde son <strong>terminal de paiement</strong> actuel.</li><li>Budget de construction : <strong>6 000 $</strong>. Mise en ligne voulue : le <strong>1<sup>er</sup> décembre</strong>.</li></ul> Ensuite, dans le Lab 08, vous refaites les mêmes étapes pour <strong>Aventure Saint-Maurice</strong>. </div>',15)),r(i),e[1]||(e[1]=s('<p>Chaque étape est présentée de la même façon : <strong>la question</strong>, <strong>la méthode</strong> en quelques gestes, <strong>l&#39;exemple</strong> de la boulangerie, puis <strong>à retenir</strong> et <strong>où ça va</strong> dans votre rapport.</p><hr><h2 id="choisir-avec-des-criteres" tabindex="-1">Étape 1 sur 4 — Choisir avec des critères <a class="header-anchor" href="#choisir-avec-des-criteres" aria-label="Permalink to &quot;Étape 1 sur 4 — Choisir avec des critères {#choisir-avec-des-criteres}&quot;">​</a></h2><p><strong>La question.</strong> Plusieurs outils font l&#39;affaire. Lequel prendre, et comment le justifier au client ?</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Écrire les critères.</strong> Chaque critère vient d&#39;une exigence ou d&#39;une contrainte déjà écrite dans le rapport. On n&#39;en invente pas.</li><li><strong>Donner un poids à chacun.</strong> 3 = indispensable, 2 = important, 1 = souhaitable.</li><li><strong>Trier les outils, du poids le plus fort au plus faible.</strong> Un outil qui échoue à un critère de poids 3 est écarté.</li></ol><p><strong>Dans la boulangerie.</strong> Les critères, et d&#39;où ils viennent :</p><table><thead><tr><th>Critère</th><th>D&#39;où il vient</th><th>Poids</th></tr></thead><tbody><tr><td>La propriétaire change le menu seule, chaque vendredi</td><td>Exigence : « le menu change toutes les semaines »</td><td>3</td></tr><tr><td>Le paiement passe par son terminal actuel</td><td>Contrainte technologique : elle garde son terminal</td><td>2</td></tr><tr><td>Moins de 50 $ par mois pour l&#39;outil de commande</td><td>Contrainte de budget : « pas plus de 50 $ par mois pour les commandes », dit la propriétaire</td><td>2</td></tr><tr><td>Un rappel par texto la veille</td><td>Exigence souhaitée : « les clients oublient »</td><td>1</td></tr></tbody></table><p>Puis le tri, de gauche à droite :</p>',9)),r(o),e[2]||(e[2]=s('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> On ne choisit pas l&#39;outil « le meilleur » : on choisit celui qui passe les critères de poids 3, puis le meilleur sur les critères de poids 2.<br><strong>Où ça va.</strong> Évaluation 2, sections 2.1 (les critères) et 2.2 (les choix). À faire à la maison, avec les <a href="./../../fiches/eval2-tableaux-communs.docx" download>tableaux de comparaison communs</a>. Ce n&#39;est pas dans le Lab 08. </div><hr><h2 id="estimer-le-travail" tabindex="-1">Étape 2 sur 4 — Estimer le travail <a class="header-anchor" href="#estimer-le-travail" aria-label="Permalink to &quot;Étape 2 sur 4 — Estimer le travail {#estimer-le-travail}&quot;">​</a></h2><p><strong>La question.</strong> Combien d&#39;heures le studio va-t-il travailler ? Studio Web FC facture <strong>75 $ de l&#39;heure</strong> (c&#39;est le taux donné dans l&#39;énoncé de l&#39;évaluation 2). Une heure oubliée dans l&#39;estimation, ce sont 75 $ que le studio paie de sa poche, ou une fonctionnalité qu&#39;il ne livre pas.</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Découper en tâches.</strong> Une tâche : une personne, une ou deux journées au plus. « Faire le site » n&#39;est pas une tâche. Puis relire la liste des cinq tâches qu&#39;on oublie :</li></ol>',6)),r(l),e[3]||(e[3]=s('<ol start="2"><li><p><strong>Donner trois chiffres par tâche, et en tirer un.</strong> Un seul chiffre, c&#39;est presque toujours le plus optimiste : on imagine la tâche qui se passe bien. Trois chiffres obligent à penser aussi à ce qui peut mal tourner.</p><p><strong>Comment trouver les trois chiffres, dans cet ordre :</strong></p><ul><li><strong>Le probable d&#39;abord.</strong> Pensez à la dernière fois que vous avez fait une tâche semblable, dans un lab ou un projet : combien de temps ça a vraiment pris ? Si vous ne l&#39;avez jamais faite, essayez-en un petit bout pendant 15 minutes, ou demandez à quelqu&#39;un qui l&#39;a déjà faite.</li><li><strong>L&#39;optimiste ensuite.</strong> Reprenez le probable et enlevez les embûches : rien à chercher, tout marche du premier coup. Il est plus petit que le probable, souvent de la moitié aux trois quarts.</li><li><strong>Le pessimiste à la fin.</strong> Écrivez ce qui peut mal tourner (un outil qu&#39;on ne connaît pas, le soutien à contacter, un texte du client en retard, un bogue) et ajoutez au probable le temps que chaque problème ferait perdre. On compte ce qui arrive vraiment de temps en temps, pas la catastrophe.</li></ul><p><strong>Puis on en tire un seul chiffre, l&#39;estimation retenue</strong>, celui qu&#39;on met au devis. On ne prend pas simplement le probable, parce qu&#39;il oublie les mauvais jours. On ne prend pas le pessimiste non plus, parce que le devis serait trop cher.</p><p><strong>D&#39;où vient le « 4 × » :</strong> imaginez que vous faites la même tâche six fois. Une fois, tout va bien (l&#39;optimiste). Une fois, ça tourne mal (le pessimiste). Les quatre autres fois, ça se passe comme d&#39;habitude (le probable, quatre fois). L&#39;estimation retenue est la moyenne de ces six fois : on additionne les six chiffres, puis on divise par 6.</p><p>Pour relier la réservation à Square : 2 + (4 + 4 + 4 + 4) + 10 = 28 heures pour six fois, donc 28 ÷ 6 ≈ <strong>4,7 h</strong> par fois. C&#39;est la méthode PERT, utilisée en gestion de projet. La fiche du Lab fait le calcul pour vous.</p></li></ol>',1)),r(u),e[4]||(e[4]=s('<ol start="3"><li><strong>Comparer à un projet semblable.</strong> Si un site semblable a pris 90 heures et que votre total en donne 45, il manque des tâches.</li></ol><div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Une tâche avec un grand écart entre l&#39;optimiste et le pessimiste est un risque : on l&#39;essaie en premier.<br><strong>Où ça va.</strong> Évaluation 2, section 5.1. Lab 08, partie 1. </div><h3 id="activite-1" tabindex="-1">Activité 1 — L&#39;estimation de la boulangerie <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — L&#39;estimation de la boulangerie {#activite-1}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min en équipe, puis 10 min de retour en grand groupe)</strong><br> Une collègue pressée a estimé le site de la boulangerie avec un seul chiffre par tâche : le probable. <ol class="list-decimal pl-5"><li><strong>Pour chaque tâche</strong>, écrivez l&#39;<strong>optimiste</strong> (plus petit que le probable), puis le <strong>pessimiste</strong> (plus grand). L&#39;estimation retenue se calcule seule.</li><li><strong>Cochez les tâches oubliées</strong> dans la deuxième liste. Aidez-vous des cinq tâches qu&#39;on oublie, plus haut.</li><li><strong>Cliquez sur « Comparer avec le projet semblable »</strong> et regardez l&#39;écart.</li><li><strong>Copiez vos réponses</strong> avec le bouton, pour les garder.</li></ol><strong>Si vous bloquez</strong> sur un chiffre : imaginez la tâche qui se passe bien (optimiste), puis la même tâche un mauvais jour (pessimiste). Un chiffre raisonnable suffit; il n&#39;y a pas de réponse exacte.<br><strong>Pour le retour en groupe :</strong> quelle tâche a le plus grand écart, et pourquoi ? </div>',4)),r(d),e[5]||(e[5]=s('<hr><h2 id="echeancier" tabindex="-1">Étape 3 sur 4 — Placer le travail dans le temps <a class="header-anchor" href="#echeancier" aria-label="Permalink to &quot;Étape 3 sur 4 — Placer le travail dans le temps {#echeancier}&quot;">​</a></h2><p><strong>La question.</strong> Le travail estimé sera-t-il fini à la date voulue ?</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Partir de la date qu&#39;on ne peut pas déplacer</strong>, et remonter vers aujourd&#39;hui.</li><li><strong>Regrouper les tâches en 4 à 6 étapes</strong> (démarrage, maquettes, construction, tests et formation…), puis ajouter un <strong>coussin</strong> : une étape à part, de 15 à 20 % de la durée.</li><li><strong>Dater tout ce que le client doit fournir</strong> : l&#39;accès au domaine, ses commentaires, ses textes et ses photos.</li></ol><p><strong>Dans la boulangerie</strong>, mise en ligne le 1<sup>er</sup> décembre :</p>',6)),r(c),e[6]||(e[6]=s('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Un texte du client en retard est la première cause de retard d&#39;un petit projet : sa date est dans l&#39;échéancier.<br><strong>Pour Aventure Saint-Maurice :</strong> la date ferme est le <strong>1<sup>er</sup> mars 2027</strong>. Pensez aux fêtes, et à la réponse de la MRC en <strong>janvier</strong> : qu&#39;est-ce qui en dépend ?<br><strong>Où ça va.</strong> Évaluation 2, section 5.2. Lab 08, partie 2. </div><hr><h2 id="devis" tabindex="-1">Étape 4 sur 4 — Chiffrer et entrer dans le budget <a class="header-anchor" href="#devis" aria-label="Permalink to &quot;Étape 4 sur 4 — Chiffrer et entrer dans le budget {#devis}&quot;">​</a></h2><p><strong>La question.</strong> Combien le projet coûte-t-il, et est-ce que ça entre dans le budget ?</p><p><strong>La méthode, en trois gestes.</strong></p><ol><li><strong>Les coûts uniques</strong> : les heures retenues × 75 $, plus ce qui s&#39;achète une fois. On les compare au <strong>budget de construction</strong>.</li><li><strong>Les coûts annuels</strong> : les abonnements, les commissions, le domaine. On les compare à <strong>ce que le client paie aujourd&#39;hui</strong>.</li><li><strong>Si ça dépasse</strong>, on ne baisse pas les heures : on propose <strong>trois façons d&#39;entrer dans le budget</strong>, et le client choisit.</li></ol><p><strong>Dans la boulangerie</strong>, le devis se lit en trois comparaisons :</p>',7)),r(p),e[7]||(e[7]=a("p",null,[n("Une commission est un pourcentage de chaque vente : pour la calculer, il faut le "),a("strong",null,"volume"),n(" de ventes d'une année. Pour Aventure Saint-Maurice, la commission ne touche que les réservations "),a("strong",null,"payées en ligne"),n(" : environ 1 800 par année (70 % des 2 600 réservations du mandat), à 120 $ en moyenne, soit 216 000 $ par année. Un outil qui prend 3 % coûte donc 216 000 $ × 3 % = 6 480 $ par année. Ce sont les hypothèses des tableaux de comparaison communs. Dans votre devis, écrivez le calcul sous le tableau.")],-1)),e[8]||(e[8]=a("p",null,"Quand le devis dépasse, trois familles de solutions :",-1)),r(g),e[9]||(e[9]=s('<div class="bg-slate-50 border border-slate-200 text-slate-900 rounded-lg p-4 mb-5"><strong>À retenir.</strong> Chaque option dit ce qu&#39;elle fait économiser <strong>et ce que le client perd</strong>. Les tests, la formation et l&#39;accessibilité ne se coupent jamais.<br><strong>Où ça va.</strong> Évaluation 2, section 6. Le devis : Lab 08, partie 3. Les trois façons d&#39;entrer dans le budget (6.4) : à la maison. </div><h3 id="activite-2" tabindex="-1">Activité 2 — Faire entrer la boulangerie dans le budget <a class="header-anchor" href="#activite-2" aria-label="Permalink to &quot;Activité 2 — Faire entrer la boulangerie dans le budget {#activite-2}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min en équipe, puis 10 min de retour en grand groupe)</strong><br> Le devis de la boulangerie dépasse son budget de 6 000 $. Vous avez six idées pour économiser. Pour chacune, vous décidez si vous la présentez à la cliente comme option. <ol class="list-decimal pl-5"><li><strong>Pour chaque économie</strong>, écrivez en une phrase <strong>ce que la cliente perd</strong> si elle l&#39;accepte.</li><li>Répondez à la question <strong>« Propose-t-on cette économie à la cliente ? »</strong><ul class="list-disc pl-5"><li><strong>Oui, on la propose</strong> : elle fait partie des options qu&#39;on présente à la cliente.</li><li><strong>Non, on garde le devis tel quel</strong> : l&#39;économie est trop risquée ou coûte plus cher plus tard. On ne la présente pas, et rien ne change dans le devis sur ce point.</li></ul></li><li><strong>Cliquez sur « Vérifier »</strong> pour voir l&#39;effet sur trois ans, puis lisez l&#39;explication des économies où vous vous êtes trompés.</li><li><strong>Copiez vos réponses</strong> avec le bouton, pour les garder.</li></ol><strong>Si vous bloquez :</strong> relisez le tableau des critères de la boulangerie (étape 1). Une économie qui fait échouer un critère de poids 3 ne se propose pas.<br><strong>Pour le retour en groupe :</strong> quelle économie avait l&#39;air bonne, mais ne l&#39;était pas pour la cliente ? </div>',3)),r(m),e[10]||(e[10]=s('<hr><h2 id="la-suite" tabindex="-1">La suite du cours et la rencontre avec le client <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La suite du cours et la rencontre avec le client {#la-suite}&quot;">​</a></h2><p>On passe de <strong>HK29</strong> (la faisabilité) à <strong>HK33</strong> (la conception) : ce que la proposition décide sera construit dans la deuxième partie du cours. Le mode agile viendra aux séances 16 et 17.</p><p>La <strong>séance 9 (25 novembre)</strong> est une <strong>rencontre avec Mélanie</strong>. Apportez <strong>cinq questions</strong>. Vous n&#39;en écrivez pas de nouvelles : vous les choisissez à la fin du Lab 08, parmi celles de votre rapport 1 (section 7.2). Gardez celles dont la réponse peut changer votre estimation, votre échéancier ou votre devis.</p><table tabindex="0"><thead><tr><th style="text-align:left;">✕ À éviter</th><th style="text-align:left;">✓ À poser</th></tr></thead><tbody><tr><td style="text-align:left;">« Est-ce que vous aimez le bleu ? »</td><td style="text-align:left;">« Quelle politique d&#39;annulation voulez-vous ? » : <strong>une question, une décision</strong></td></tr><tr><td style="text-align:left;">« Avez-vous besoin d&#39;un mode hors ligne ? »</td><td style="text-align:left;">« Les guides doivent-ils voir la liste au quai, sans réseau ? » : <strong>dans ses mots à elle</strong></td></tr></tbody></table><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab08-estimer-et-chiffrer">Lab 08 — Estimer et chiffrer la proposition</a>, en équipe. Gardez votre rapport de l&#39;évaluation 1 sous la main. Le lab reprend les étapes 2 et 3, puis le devis de l&#39;étape 4. Les trois façons d&#39;entrer dans le budget se font à la maison.</p><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><ul><li><strong>Terminer le Lab 08</strong> : la fiche devient vos sections 5 et 6.</li><li><strong>Écrire vos choix (section 2.2)</strong> à partir de vos critères (section 2.1). N&#39;attendez pas la rencontre.</li><li><strong>Écrire les trois façons d&#39;entrer dans le budget (section 6.4)</strong>, comme dans l&#39;activité 2.</li></ul><hr><h2 id="avant-la-seance-9-25-novembre" tabindex="-1">Avant la séance 9 (25 novembre) <a class="header-anchor" href="#avant-la-seance-9-25-novembre" aria-label="Permalink to &quot;Avant la séance 9 (25 novembre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Copier vos réponses des activités 1 et 2 dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 08, avec vos cinq questions pour Mélanie, dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Avoir un premier jet de la section 2.2 pour les cinq questions</span></label></li></ul>',14))])}const S=h(f,[["render",q]]);export{y as __pageData,S as default};
